/* Explicit playtest navigation: no synthetic victories, XP, or order progress. */
(function(root){'use strict';const G=root.Game,A=root.JourneyActs,T=root.JourneyTree;
function allowed(s){return A.ensure(s)&&!s.meta?.ended&&!s.training&&!s.tutorialReplay&&s.phase!=='battle'&&s.phase!=='tree'&&!s.pendingRelic;}
function reset(s){s.current=null;s.phase='map';s.round=0;s.score=[0,0];s.energy=0;s.ai=null;s.board=Array(15).fill(null);s.bench=Array(6).fill(null);s.draw=[];s.discard=[];s.hand=[];s.fusions={};s.handFrozen=false;s.deployedAt={};s.returnable={};s.offers=null;s.eventPending=null;s.eventEncounter=null;s.enemyRevealed=false;delete s.raid;delete s.bossEncounter;delete s.tutorial;}
function debug(s){const j=A.ensure(s);return j.debug??={maps:{},jumps:[]};}
function remember(s){const d=debug(s),route=[...s.route];let layer=s.layer,resumeNode=null;if(s.current&&s.phase!=='map'){if(s.meta?.completed?.includes(s.current.id))layer=Math.min(14,layer+1);else{resumeNode=s.current.id;if(route.at(-1)===s.current.id)route.pop();}}d.maps[A.act(s)]={map:s.map,route,layer,resumeNode,campaignRoute:s.campaignRoute,battleStart:s.journey.battleStart};}
function jumpMap(s,a){if(!allowed(s)||![1,2,3].includes(a))return false;const old=A.act(s),d=debug(s);remember(s);const saved=d.maps[a];s.journey.act=a;reset(s);if(saved){s.map=saved.map;s.route=[...saved.route];s.layer=saved.layer;s.campaignRoute=saved.campaignRoute;s.journey.battleStart=saved.battleStart;if(saved.resumeNode)d.pendingNode=saved.resumeNode;else delete d.pendingNode;}else{s.map=A.generate(s.seed,a,s.journey.seenMonsters||[]);s.route=[];s.layer=0;s.campaignRoute={schema:1,act:a,defeatedForces:[],wonNodes:[],dawncrestForces:[],dawncrestNodes:[],monsterNodes:[],boss:null,bossDefeated:false};s.journey.battleStart=s.mapBattles||0;}if(a!==old)T.grantEntry(s);d.jumps.push({kind:'map',from:old,to:a});return true;}
function available(s){const id=s.journey?.debug?.pendingNode;if(!id||s.phase!=='map')return null;const n=s.map.flat().find(n=>n.id===id&&n.layer===s.layer);return n?[n]:null;}
function jumpNode(s,id){if(!allowed(s))return false;const n=s.map.flat().find(n=>n.id===id);if(!n)return false;const d=debug(s);reset(s);s.layer=n.layer;s.journey.battleStart=(s.mapBattles||0)-A.SPEC[A.act(s)].fights.filter(l=>l<n.layer).length;d.pendingNode=id;const ok=G.enter(s,id);delete d.pendingNode;if(ok)d.jumps.push({kind:'node',act:A.act(s),id});return ok;}
const enter=G.enter;G.enter=function(s,id){const ok=enter(s,id);if(ok&&s.journey?.debug)delete s.journey.debug.pendingNode;return ok;};
root.JourneyDebug={allowed,jumpMap,jumpNode,available};
})(typeof globalThis!=='undefined'?globalThis:this);
